#include "field_mod.hpp"
#include <algorithm>
#include <tuple>
Rat lc(const Rat&v){Rat c;slong var=1;ulong power=nmod_mpoly_degree_si(v.n,1,ctx);nmod_mpoly_get_coeff_vars_ui(c.n,v.n,&var,&power,1,ctx);return c;}
void primitive(Row&r){Rat g,t,c;slong var=1;for(auto&[j,v]:r){assert(nmod_mpoly_content_vars(c.n,v.n,&var,1,ctx));assert(nmod_mpoly_degree_si(c.n,1,ctx)<=0);assert(nmod_mpoly_gcd(t.n,g.n,c.n,ctx));nmod_mpoly_swap(t.n,g.n,ctx);if(nmod_mpoly_total_degree_si(g.n,ctx)==0)break;}if(g.zero())return;for(auto&[j,v]:r){assert(nmod_mpoly_divides(t.n,v.n,g.n,ctx));nmod_mpoly_swap(t.n,v.n,ctx);}}
void rowSubtract(Row&b,const Row&a,const Rat&pa,const Rat&pb){Rat tmp,t;for(auto&[j,v]:b){nmod_mpoly_mul(tmp.n,v.n,pa.n,ctx);nmod_mpoly_swap(tmp.n,v.n,ctx);}for(auto&[j,v]:a){nmod_mpoly_mul(tmp.n,pb.n,v.n,ctx);nmod_mpoly_sub(t.n,b[j].n,tmp.n,ctx);if(t.zero())b.erase(j);else nmod_mpoly_swap(t.n,b[j].n,ctx);}primitive(b);}

pair<int,int>lead(const Row&r){int degree=-1,col=-1;for(auto&[j,v]:r){int d=nmod_mpoly_degree_si(v.n,1,ctx);if(d>degree||(d==degree&&j>col)){degree=d;col=j;}}return{degree,col};}
int main(int argc,char**argv){nmod_mpoly_ctx_init(ctx,2,ORD_LEX,prime);{ifstream in(argv[1]);int nr,nc;in>>nr>>nc;vector<Row>A(nr),B(nc);for(auto&row:A){int n;in>>n;Rat den,g,t;nmod_mpoly_one(den.n,ctx);for(int k=0;k<n;k++){int j;in>>j;Rat x;readpoly(in,x.n);readpoly(in,x.d);nmod_mpoly_evaluate_one_ui(x.n,x.n,0,2,ctx);nmod_mpoly_evaluate_one_ui(x.d,x.d,0,2,ctx);assert(nmod_mpoly_degree_si(x.d,1,ctx)<=0);assert(nmod_mpoly_gcd(g.n,den.n,x.d,ctx));assert(nmod_mpoly_divides(t.n,x.d,g.n,ctx));nmod_mpoly_mul(g.n,den.n,t.n,ctx);nmod_mpoly_swap(g.n,den.n,ctx);if(!x.zero())row.emplace(j,std::move(x));}for(auto&[j,v]:row){assert(nmod_mpoly_divides(t.n,den.n,v.d,ctx));nmod_mpoly_mul(g.n,t.n,v.n,ctx);nmod_mpoly_swap(g.n,v.n,ctx);nmod_mpoly_one(v.d,ctx);}primitive(row);}
vector<pair<pair<int,long>,int>> order;for(int i=0;i<nr;i++){long terms=0;for(auto&[j,v]:A[i])terms+=nmod_mpoly_length(v.n,ctx);order.push_back({{lead(A[i]).first,terms},i});}sort(order.begin(),order.end());int steps=0,rank=0;for(auto[score,i]:order){Row row=std::move(A[i]);while(!row.empty()){auto[d,c]=lead(row);if(B[c].empty()){B[c]=std::move(row);rank++;break;}auto[bd,bc]=lead(B[c]);assert(bc==c);if(d<bd){row.swap(B[c]);swap(d,bd);}Rat pa=lc(B[c][c]),pb=lc(row[c]);if(d>bd){Rat mon,t;ulong ex[2]={0,ulong(d-bd)};nmod_mpoly_set_coeff_ui_ui(mon.n,1,ex,ctx);nmod_mpoly_mul(t.n,pb.n,mon.n,ctx);nmod_mpoly_swap(t.n,pb.n,ctx);}rowSubtract(row,B[c],pa,pb);auto nd=lead(row);assert(row.empty()||nd.first<d||(nd.first==d&&nd.second<c));if(++steps%50==0)cerr<<"step "<<steps<<" input "<<i<<" rank "<<rank<<" active degree "<<nd.first<<'\n';}int sum=0;for(auto&r:B)if(!r.empty())sum+=lead(r).first;cerr<<"row "<<i<<" rank "<<rank<<" indexdegree "<<sum<<" steps "<<steps<<'\n';}
ofstream out(argv[2]);out<<rank<<' '<<nc<<'\n';for(int c=0;c<nc;c++)if(!B[c].empty()){auto&r=B[c];out<<c<<' '<<r.size()<<'\n';for(auto&[j,v]:r){out<<j<<'\n';writepoly(out,v.n);writepoly(out,v.d);}}}nmod_mpoly_ctx_clear(ctx);flint_cleanup();}
